'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pretty=x=>JSON.stringify(x,null,2);const tests=window.Fixtures,model=window.RefEngine;let results={},adrs=[];
$('#total-tests').textContent=tests.length;$('#test-tab-count').textContent=tests.length;
function currentResult(t){return results[t.id]||( {status:'ready'} )}
function selectedTests(){let area=$('#case-filter').value,status=$('#result-filter').value;return tests.filter(t=>(area==='all'||t.group===area)&&(status==='all'||currentResult(t).status===status))}
function mismatch(a,b,path='$'){if(model.same(a,b))return '';if(a===null||b===null||typeof a!=='object'||typeof b!=='object'||!a||!b||Array.isArray(a)!==Array.isArray(b))return path;if(Array.isArray(a)){if(a.length!==b.length)return `${path}.length`;for(let i=0;i<a.length;i++){let k=mismatch(a[i],b[i],`${path}[${i}]`);if(k)return k}return path}for(let k of new Set([...Object.keys(a),...Object.keys(b)])){if(!(k in a)||!(k in b))return `${path}.${k}`;let d=mismatch(a[k],b[k],`${path}.${k}`);if(d)return d}return path}
function drawTests(openId){const items=selectedTests();$('#case-count').textContent=`${items.length} / ${tests.length} cases`;$('#test-empty').hidden=items.length>0;$('#test-list').innerHTML=items.map(t=>{let r=currentResult(t);let has=r.status!=='ready';return `<details class="test-card" id="case-${esc(t.id)}" ${openId===t.id?'open':''}><summary><span class="test-num">${esc(t.id)}</span><span class="test-title">${esc(t.title)}</span><span class="group-tag">${esc(t.group)}</span><span class="pill ${esc(r.status)}">${esc(r.status)}</span></summary><div class="test-body"><div class="test-meta"><span>ADR ${t.adr.map(a=>`<a href="#decisions" data-adr="ADR-${esc(a)}">${esc(a)}</a>`).join(' · ')}</span><button class="run-one" type="button" data-run="${esc(t.id)}">▶ Run case</button></div><div class="detail-grid"><div class="detail-box"><strong>INPUTS / ORDERED</strong><pre>${esc(pretty(t.inputs))}</pre></div><div class="detail-box"><strong>PROJECTION / CONFIGURATION</strong><pre>${esc(pretty(t.config))}</pre></div><div class="detail-box"><strong>EXPECTED</strong><pre>${esc(pretty(t.expected))}</pre></div><div class="detail-box actual"><strong>ACTUAL / EXAMPLE MODEL</strong><pre>${has?esc(pretty(r.actual)):'Run the case to see its result.'}</pre></div></div>${r.status==='fail'?`<p class="mismatch">Difference: ${esc(r.difference||'execution error')}</p>`:''}</div></details>`}).join('')}
function score(){let ran=Object.values(results),pass=ran.filter(r=>r.status==='pass').length,fail=ran.filter(r=>r.status==='fail').length;let box=$('#run-status');box.classList.toggle('failed',fail>0);box.innerHTML=ran.length?`<b>${pass}<span> / ${ran.length}</span></b><span>${fail?`${fail} FAILED`:'PASSED'}</span>`:'<b>—</b><span>READY</span>';$('#run-meter-fill').style.width=`${ran.length/tests.length*100}%`}
function execute(t){try{let actual=t.run(t.config,t.inputs,{repeatDefect:$('#inject-defect').checked});let status=model.same(t.expected,actual)?'pass':'fail';return {status,actual,difference:status==='fail'?mismatch(t.expected,actual):''}}catch(e){return {status:'fail',actual:{error:e.message},difference:'execution error'}}}
function runAll(){results={};for(let t of tests)results[t.id]=execute(t);score();drawTests()}
function tab(name){if(!document.getElementById(name))return;if(location.hash!=='#'+name)location.hash=name;document.querySelectorAll('.eval-tabs [role=tab]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.panel===name)));document.querySelectorAll('.panel').forEach(p=>p.hidden=p.id!==name)}
document.querySelectorAll('.eval-tabs button').forEach(b=>b.addEventListener('click',()=>tab(b.dataset.panel)));document.querySelectorAll('[data-open-panel]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();tab(a.dataset.openPanel);document.querySelector('.eval-tabs').scrollIntoView({behavior:'smooth',block:'start'})}));
$('#run-suite').addEventListener('click',runAll);$('#reset-suite').addEventListener('click',()=>{results={};$('#inject-defect').checked=false;score();drawTests()});$('#inject-defect').addEventListener('change',()=>{results={};score();drawTests()});$('#case-filter').addEventListener('change',()=>drawTests());$('#result-filter').addEventListener('change',()=>drawTests());
$('#test-list').addEventListener('click',e=>{const run=e.target.closest('[data-run]');if(run){let id=run.dataset.run,t=tests.find(x=>x.id===id);results[id]=execute(t);score();drawTests(id);return}const link=e.target.closest('[data-adr]');if(link){e.preventDefault();tab('decisions');$('#adr-search').value=link.dataset.adr;$('#adr-status').value='all';drawAdrs();const target=document.getElementById(link.dataset.adr);if(target){target.open=true;target.scrollIntoView({behavior:'smooth',block:'start'})}}});
function inlineText(s){return esc(s).replace(/\*\*(.*?)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>')}
function markdown(s){return s.split('\n').map(line=>{line=line.trim();if(!line)return '';if(line.startsWith('### '))return `<h4>${inlineText(line.slice(4))}</h4>`;if(line.startsWith('- '))return `<p class="adr-bullet">${inlineText(line.slice(2))}</p>`;return `<p>${inlineText(line)}</p>`}).join('')}
function drawAdrs(){let term=$('#adr-search').value.toLowerCase().trim(),filter=$('#adr-status').value;let items=adrs.filter(a=>{let status=a.status.toLowerCase(),kind=/supersed|clarified/.test(status)?'superseded':status.includes('accepted')?'accepted':'other';return (filter==='all'||kind===filter)&&(`${a.id} ${a.title} ${a.body}`.toLowerCase().includes(term))});$('#adr-count').textContent=`${items.length} / ${adrs.length}`;$('#adr-list').innerHTML=items.map(a=>`<details class="adr-card" id="${esc(a.id)}"><summary><span class="adr-id">${esc(a.id)}</span><span class="adr-title">${esc(a.title)}</span><span class="pill">${esc(a.status.replace(/\s+/g,' ').replace(/\*\*/g,''))}</span></summary><div class="adr-body">${markdown(a.body)}</div></details>`).join('');if(adrs.length&&!items.length)$('#adr-list').innerHTML='<div class="empty-state">No decisions match this search.</div>'}
fetch('adrs.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(data=>{adrs=data;const requested=new URLSearchParams(location.search).get('adr');if(requested&&/^ADR-\d{3}$/.test(requested))$('#adr-search').value=requested;drawAdrs();if(requested){const card=document.getElementById(requested);if(card)card.open=true}}).catch(()=>{$('#adr-error').hidden=false});$('#adr-search').addEventListener('input',drawAdrs);$('#adr-status').addEventListener('change',drawAdrs);drawTests();score();if(['plan','simulation','decisions'].includes(location.hash.slice(1)))tab(location.hash.slice(1));
